# Dekopon publishes one archive per platform. Each formula installs its own executables.
#
# Generated by .github/scripts/render-homebrew-formula.py in
# https://github.com/dekopon-agents/dekopon, from the archives release v0.61.1 published.
# Which platforms Dekopon supports is a property of each release, not of this
# tap. Edit the generator, not this file.
class Dekopon < Formula
  desc "Capability-oriented control plane for self-hosted AI agents"
  homepage "https://github.com/dekopon-agents/dekopon"
  license any_of: ["Apache-2.0", "MIT"]
  # No explicit `version`: Homebrew scans 0.61.1 out of the download URL, and
  # `brew audit --strict` rejects restating it.

  on_macos do
    on_arm do
      url "https://github.com/dekopon-agents/dekopon/releases/download/v0.61.1/dekopon-0.61.1-aarch64-apple-darwin.tar.gz"
      sha256 "fed4e095bfb84102bf2f0b13d4fbd3e70ec6649272b68a63c776166ed01cc111"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/dekopon-agents/dekopon/releases/download/v0.61.1/dekopon-0.61.1-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "d8280a5b09fb60e73e93abb4ff75a78142d800a05124fbaba7f4404bd1a214df"
    end

    on_intel do
      url "https://github.com/dekopon-agents/dekopon/releases/download/v0.61.1/dekopon-0.61.1-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "9a108b16e14902f48708817b73d23bfa1a20091b7334047b4c75ec654625e9cc"
    end
  end

  def install
    bin.install "dekopon-brokerd", "dekopon-gatewayd"
    doc.install "README.md", "BROKER.md", "GATEWAY.md", "LICENSE-APACHE", "LICENSE-MIT"
  end

  def caveats
    <<~EOS
      Dekopon installed two executables:

        dekopon-brokerd   the authorization broker daemon (Unix only)
        dekopon-gatewayd  the unprivileged chat gateway daemon (Unix only)

      Manage model authentication without starting a daemon:

        dekopon-gatewayd auth chatgpt --help

      Check a configuration offline, as startup would, before deploying it:

        dekopon-brokerd check broker.d --provider-set providers.yaml --store DIR
        dekopon-gatewayd check gatewayd.d --catalog agents.d

      dekopon-brokerd and dekopon-gatewayd are daemons. Nothing was started, and neither
      runs until you write it an owner-authored configuration file:

        dekopon-brokerd --config broker.yaml    #{doc}/BROKER.md
        dekopon-gatewayd --config gateway.yaml          #{doc}/GATEWAY.md

      The broker holds provider credentials and the only authorization path;
      read BROKER.md before enabling it.

      The end-to-end walkthrough is examples/conditional-write in the source tree:
      https://github.com/dekopon-agents/dekopon/tree/v0.61.1/examples/conditional-write/README.md
    EOS
  end

  test do
    assert_match "dekopon-brokerd #{version}", shell_output("#{bin}/dekopon-brokerd --version")
    assert_match "dekopon-gatewayd #{version}", shell_output("#{bin}/dekopon-gatewayd --version")

    assert_match "--expose-credential",
                 shell_output("#{bin}/dekopon-gatewayd auth chatgpt export --help")
    assert_match '"signedIn": false',
                 shell_output("#{bin}/dekopon-gatewayd auth chatgpt status --auth-file #{testpath}/missing-auth.json -o json")
  end
end
